function deepMerge(base, over) {
  if (over === null || over === undefined) return base;
  if (Array.isArray(base) || typeof base !== 'object' || base === null) return over;
  if (typeof over !== 'object' || Array.isArray(over)) return over;
  const out = { ...base };
  for (const k of Object.keys(over)) {
    out[k] = k in base ? deepMerge(base[k], over[k]) : over[k];
  }
  return out;
}

// ---------------------------------------------------------------- project

const readText = (p) => fs.readFileSync(p, 'utf8').replace(/\r\n/g, '\n');

function writeText(p, text) {
  fs.writeFileSync(p, text.endsWith('\n') ? text : text + '\n');
}

function findRoot(start) {
  let dir = path.resolve(start);
  for (;;) {
    if (fs.existsSync(path.join(dir, 'specs', 'flow.config.yml'))) return dir;
    const up = path.dirname(dir);
    if (up === dir) return null;
    dir = up;
  }
}

function loadProject(start = process.cwd()) {
  const root = findRoot(start);
  if (!root) fail('No specs/flow.config.yml found from here upwards. Run `flow init --key ABC` first.');
  const configPath = path.join(root, 'specs', 'flow.config.yml');
  const config = deepMerge(DEFAULTS, parseYaml(readText(configPath), 'specs/flow.config.yml'));
  if (!config.key || !/^[A-Z]{3,4}$/.test(config.key)) fail('specs/flow.config.yml: "key" must be 3-4 capital letters');
  return {
    root,
    configPath,
    config,
    specsDir: path.join(root, 'specs'),
    ticketsDir: path.join(root, config.paths.tickets),
    generalDir: path.join(root, config.paths.general_spec),
    indexPath: path.join(root, config.paths.index),
  };
}

// ---------------------------------------------------------------- tickets

function splitFrontmatter(text, where = 'file') {
  const lines = text.split('\n');
  if (lines[0] !== '---') fail(`${where}: missing frontmatter (file must start with ---)`);
  let end = -1;
  for (let i = 1; i < lines.length; i++) {
    if (lines[i] === '---') {
      end = i;
      break;
    }
  }
  if (end < 0) fail(`${where}: frontmatter is not closed with ---`);
  return { fm: lines.slice(1, end).join('\n'), body: lines.slice(end + 1).join('\n') };
}

function reparse(t) {
  const { fm, body } = splitFrontmatter(t.text, t.rel || t.file);
  t.fmText = fm;
  t.body = body;
  t.data = parseYaml(fm, t.rel || t.file);
  t.id = t.data.id ?? path.basename(t.file, '.md');
  return t;
}

function loadTicketFile(ctx, file) {
  const t = { file, rel: posix(path.relative(ctx.root, file)), text: readText(file) };
  return reparse(t);
}

const idNum = (id) => Number((String(id).match(/-(\d+)$/) || [])[1] ?? 0);
const byId = (a, b) => idNum(a) - idNum(b);

function loadAll(ctx) {
  const tickets = new Map();
  const errors = [];
  if (!fs.existsSync(ctx.ticketsDir)) return { tickets, errors };
  const files = fs
    .readdirSync(ctx.ticketsDir)
    .filter((f) => f.endsWith('.md'))
    .sort((a, b) => byId(a.replace('.md', ''), b.replace('.md', '')));
  for (const f of files) {
    try {
      const t = loadTicketFile(ctx, path.join(ctx.ticketsDir, f));
      t.fileId = f.replace(/\.md$/, '');
      tickets.set(t.fileId, t);
    } catch (e) {
      if (!(e instanceof FlowError)) throw e;
      errors.push(e.message);
    }
  }
  return { tickets, errors };
}

function loadTicket(ctx, id) {
  const file = path.join(ctx.ticketsDir, `${id}.md`);
  if (!fs.existsSync(file)) fail(`Ticket ${id} not found (${posix(path.relative(ctx.root, file))})`);
  const t = loadTicketFile(ctx, file);
  t.fileId = id;
  return t;
}

function saveTicket(t) {
  writeText(t.file, t.text);
  return reparse(t);
}

function setFm(t, keys, value) {
  const { fm, body } = splitFrontmatter(t.text, t.rel);
  const nfm = setYamlPath(fm, keys, value);
  t.text = `---\n${nfm}\n---\n${body}`;
  return reparse(t);
}

// ---------------------------------------------------------------- body sections

const inFence = () => {
  let on = false;
  return (line) => {
    if (/^\s*```/.test(line)) {
      on = !on;
      return true;
    }
    return on;
  };
};

function getSection(body, headingPrefix, level = 2) {
  const lines = body.split('\n');
  const want = '#'.repeat(level) + ' ' + headingPrefix.toLowerCase();
  const fence = inFence();
  let start = -1;
  for (let i = 0; i < lines.length; i++) {
    if (fence(lines[i])) continue;
    if (lines[i].trim().toLowerCase().startsWith(want)) {
      start = i + 1;
      break;
    }
  }
  if (start < 0) return null;
  const fence2 = inFence();
  let end = lines.length;
  for (let i = start; i < lines.length; i++) {
    if (fence2(lines[i])) continue;
    const m = lines[i].match(/^(#{1,6}) /);
    if (m && m[1].length <= level) {
      end = i;
      break;
    }
  }
  return lines.slice(start, end).join('\n');
}

const stripHtmlComments = (s) => s.replace(/<!--[\s\S]*?-->/g, '');
const isBlankSection = (s) => {
  if (s === null) return true;
  const t = stripHtmlComments(s).trim();
  return t === '' || /^(none\.?|n\/a)$/i.test(t);
};

// ---------------------------------------------------------------- checklist

const ITEM_RE = /^- \[([ x])\] (C\d+) — (.*) · verify: (.*) · impl: (yes|no) · spec: (yes|no)\s*$/;

const validVerify = (v) => /^(test|manual|command\(.+\))$/.test(v);

function parseChecklist(body) {
  const items = [];
  const malformed = [];
  stripHtmlComments(body)
    .split('\n')
    .forEach((line) => {
      const m = line.match(ITEM_RE);
      if (m) items.push({ id: m[2], desc: m[3], verify: m[4], impl: m[5] === 'yes', spec: m[6] === 'yes' });
      else if (/^- \[[ x]\] C\d+\b/.test(line)) malformed.push(line);
    });
  return { items, malformed };
}

function setItemFlag(text, itemId, flag, value) {
  const lines = text.split('\n');
  let inComment = false;
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (line.includes('<!--')) inComment = true;
    const was = inComment;
    if (line.includes('-->')) inComment = false;
    if (was) continue;
    const m = line.match(ITEM_RE);
    if (!m || m[2] !== itemId) continue;
    const impl = flag === 'impl' ? value : m[5] === 'yes';
    const spec = flag === 'spec' ? value : m[6] === 'yes';
    const box = impl && spec ? 'x' : ' ';
    lines[i] = `- [${box}] ${m[2]} — ${m[3]} · verify: ${m[4]} · impl: ${impl ? 'yes' : 'no'} · spec: ${spec ? 'yes' : 'no'}`;
    return lines.join('\n');
  }
  fail(`Checklist item ${itemId} not found`);
}

// ---------------------------------------------------------------- change log

function parseLog(body) {
  const sec = getSection(body, 'Change log');
  if (!sec) return [];
  const rows = [];
  for (const line of sec.split('\n')) {
    const s = line.trim();
    if (!s.startsWith('|')) continue;
    const cells = s.slice(1, s.endsWith('|') ? -1 : undefined).split('|').map((c) => c.trim());
    if (cells.length < 4) continue;
    if (/^[-: ]+$/.test(cells[0])) continue;
    if (cells[0].toLowerCase() === 'date') continue;
    rows.push({ date: cells[0], action: cells[1], change: cells[2], reason: cells.slice(3).join(' | ') });
  }
  return rows;
}

function parseChange(change) {
  const m = String(change).match(/^([\w.]+): (.*) → (.*)$/);
  return m ? { field: m[1], from: m[2], to: m[3] } : null;
}

function appendLogRow(text, { date, action, change, reason }) {
  const lines = text.split('\n');
  const hi = lines.findIndex((l) => /^## Change log/i.test(l));
  if (hi < 0) fail('Ticket has no "## Change log" section');
  let last = -1;
  for (let i = hi + 1; i < lines.length; i++) if (lines[i].trim().startsWith('|')) last = i;
  const row = `| ${sanitizeCell(date)} | ${sanitizeCell(action)} | ${sanitizeCell(change)} | ${sanitizeCell(reason)} |`;
  if (last < 0) {
    lines.push('', '| Date | Action | Change | Reason |', '|---|---|---|---|', row);
  } else {
    lines.splice(last + 1, 0, row);
  }
  return lines.join('\n');
}

function logRow(t, action, change, reason, date = todayStr()) {
  if (!reason || !String(reason).trim()) fail('A reason is required for every change');
  t.text = appendLogRow(t.text, { date, action, change, reason });
  return reparse(t);
}

// ---------------------------------------------------------------- globs and files

function globToRegex(glob) {
  let re = '';
  for (let i = 0; i < glob.length; i++) {
    const c = glob[i];
    if (c === '*') {
      if (glob[i + 1] === '*') {
        i++;
        if (glob[i + 1] === '/') {
          i++;
          re += '(?:.*/)?';
        } else re += '.*';
      } else re += '[^/]*';
    } else if (c === '?') re += '[^/]';
    else if ('\\^$+.()|{}[]'.includes(c)) re += '\\' + c;
    else re += c;
  }
  return new RegExp('^' + re + '$');
}

const SKIP_DIRS = new Set(['node_modules', '.git', 'dist', 'build', 'coverage', '.next', '.turbo']);

function walkFiles(root, rel = '') {
  const out = [];
  const dir = path.join(root, rel);
  let entries = [];
  try {
    entries = fs.readdirSync(dir, { withFileTypes: true });
  } catch {
    return out;
  }
  for (const e of entries) {
    if (e.isDirectory()) {
      if (SKIP_DIRS.has(e.name)) continue;
      out.push(...walkFiles(root, rel ? `${rel}/${e.name}` : e.name));
    } else if (e.isFile()) out.push(rel ? `${rel}/${e.name}` : e.name);
  }
  return out;
}

const githubSlug = (heading) =>
  heading
    .toLowerCase()
    .replace(/`/g, '')
    .replace(/[^\p{L}\p{N}\s_-]/gu, '')
    .trim()
    .replace(/ /g, '-');

// Sections of the general spec: [{ key: "file.md#slug", file, slug, heading, summary }]
function scanSpec(ctx) {
  const out = [];
  if (!fs.existsSync(ctx.generalDir)) return out;
  for (const rel of walkFiles(ctx.generalDir).filter((f) => f.endsWith('.md')).sort()) {
    const lines = readText(path.join(ctx.generalDir, rel)).split('\n');
    const fence = inFence();
    for (let i = 0; i < lines.length; i++) {
      if (fence(lines[i])) continue;
      const m = lines[i].match(/^(#{2,3}) (.+?)\s*$/);
      if (!m) continue;
      let summary = '';
      const fence2 = inFence();
      let inComment = false;
      for (let j = i + 1; j < lines.length; j++) {
        const l = lines[j];
        if (fence2(l)) break;
        if (inComment) {
          if (l.includes('-->')) inComment = false;
          continue;
        }
        if (l.trim().startsWith('<!--')) {
          if (!l.includes('-->')) inComment = true;
          continue;
        }
        if (!l.trim()) continue;
        if (l.startsWith('#') || l.trim().startsWith('|')) break;
        summary = l.replace(/^[-*>\s]+/, '').replace(/[`*_]/g, '').trim();
        break;
      }
      if (summary.length > 110) summary = summary.slice(0, 107) + '...';
      const slug = githubSlug(m[2]);
      out.push({ key: `${rel}#${slug}`, file: rel, slug, heading: m[2], summary });
    }
  }
  return out;
}

function specRefParts(ref) {
  const s = String(ref).replace(/^\.\//, '');
  const i = s.indexOf('#');
  return i < 0 ? { file: s, slug: null } : { file: s.slice(0, i), slug: s.slice(i + 1) };
}

// Resolve a touches.spec entry to a path inside the general spec folder.
function specRefFile(ctx, ref) {
  const { file } = specRefParts(ref);
  const candidates = [file, file.replace(/^specs\/general\//, ''), file.replace(new RegExp('^' + ctx.config.paths.general_spec + '/'), '')];
  for (const c of candidates) if (fs.existsSync(path.join(ctx.generalDir, c)) && fs.statSync(path.join(ctx.generalDir, c)).isFile()) return c;
  return null;
}


// ---------------------------------------------------------------- derived model

function deriveFromLog(log) {
  const r = {
    created: log[0]?.date ?? null,
    started: null,
    finished: null,
    firstCommit: null,
    slips: 0,
    blockedSince: null,
    blockedDays: 0,
    statusHistory: [],
    itemsClosed: [],
    initialStatus: null,
  };
  for (const row of log) {
    const c = parseChange(row.change);
    if (!c) continue;
    if (c.field === 'status') {
      if (c.from === 'null' && r.initialStatus === null) r.initialStatus = c.to;
      r.statusHistory.push({ date: row.date, from: c.from, to: c.to });
      if (!r.started && ['in_progress', 'validating', 'done'].includes(c.to)) r.started = row.date;
      if (c.to === 'done') r.finished = row.date;
      else if (c.from === 'done') r.finished = null;
      if (c.to === 'blocked') r.blockedSince = row.date;
      else if (c.from === 'blocked') {
        if (r.blockedSince) r.blockedDays += daysBetween(r.blockedSince, row.date);
        r.blockedSince = null;
      }
    } else if (c.field === 'commitment_date') {
      if (r.firstCommit === null && c.to !== 'null') r.firstCommit = c.to;
      if (c.from !== 'null' && c.to !== 'null' && c.to > c.from) r.slips++;
    } else if (/^C\d+\.spec$/.test(c.field) && c.to === 'yes') r.itemsClosed.push(row.date);
  }
  return r;
}

const isOverdue = (t, today) =>
  !!t.commitment && today > t.commitment && !['done', 'cancelled'].includes(t.derived_status ?? t.status) && !t.obsolete;

function buildModel(ctx, loaded = loadAll(ctx)) {
  const today = todayStr();
  const tickets = new Map();
  for (const [fid, t] of loaded.tickets) {
    const d = t.data;
    const log = parseLog(t.body);
    const dv = deriveFromLog(log);
    const { items, malformed } = parseChecklist(t.body);
    const id = d.id ?? fid;
    tickets.set(id, {
      id,
      fileId: fid,
      file: t.file,
      rel: t.rel,
      title: d.title ?? '',
      type: d.type,
      status: d.status,
      priority: d.priority ?? 'medium',
      quick: d.quick === true,
      epic: d.epic ?? null,
      subproject: asList(d.subproject),
      module: asList(d.module),
      feature: asList(d.feature),
      assignee: d.assignee ?? null,
      requester: d.requester ?? null,
      commitment: d.commitment_date ?? null,
      depends_on: asList(d.depends_on),
      supersedes: asList(d.supersedes),
      fm: { blocks: asList(d.blocks), superseded_by: d.superseded_by ?? null, obsolete: d.obsolete === true },
      touches: {
        spec: asList(d.touches?.spec),
        scenarios: asList(d.touches?.scenarios),
        code_scope: asList(d.touches?.code_scope),
      },
      claude_md: d.claude_md ?? 'pending',
      log,
      items,
      malformed,
      body: t.body,
      data: d,
      ...dv,
    });
  }

  const blocks = new Map();
  const supersededBy = new Map();
  for (const x of tickets.values()) {
    for (const dep of x.depends_on) {
      if (!blocks.has(dep)) blocks.set(dep, []);
      blocks.get(dep).push(x.id);
    }
    if (x.status === 'done') {
      for (const a of x.supersedes) {
        const cur = supersededBy.get(a);
        if (!cur || (tickets.get(cur).finished ?? '') < (x.finished ?? '')) supersededBy.set(a, x.id);
      }
    }
  }
  for (const x of tickets.values()) {
    x.blocks = (blocks.get(x.id) ?? []).sort(byId);
    x.superseded_by = supersededBy.get(x.id) ?? null;
    x.obsolete = x.superseded_by !== null;
    x.derived_status = x.status;
    x.original_commitment = x.firstCommit ?? x.commitment;
    x.slip_days = x.firstCommit && x.commitment ? Math.max(0, daysBetween(x.firstCommit, x.commitment)) : 0;
    x.manual_pending = x.items.filter((i) => i.verify === 'manual' && !i.impl).length;
  }
  for (const e of tickets.values()) {
    if (e.type !== 'epic') continue;
    const kids = [...tickets.values()].filter((k) => k.epic === e.id).sort((a, b) => byId(a.id, b.id));
    const live = kids.filter((k) => k.status !== 'cancelled');
    const done = live.filter((k) => k.status === 'done');
    e.children = kids.map((k) => k.id);
    e.progress = { done: done.length, total: live.length };
    if (e.status === 'cancelled') e.derived_status = 'cancelled';
    else if (live.length > 0 && done.length === live.length) e.derived_status = 'done';
    else if (live.some((k) => ['in_progress', 'validating', 'blocked', 'done'].includes(k.status))) e.derived_status = 'in_progress';
  }
  for (const x of tickets.values()) x.overdue = isOverdue(x, today);
  return { ctx, today, tickets, errors: loaded.errors };
}

const sortedTickets = (model) => [...model.tickets.values()].sort((a, b) => byId(a.id, b.id));

// ---------------------------------------------------------------- INDEX.md

const cell = (s) => String(s ?? '').replace(/\|/g, '/').replace(/\n/g, ' ');
const listCell = (a) => (a.length ? a.join(', ') : '—');
const table = (head, rows) =>
  rows.length
    ? [`| ${head.join(' | ')} |`, `|${head.map(() => '---').join('|')}|`, ...rows.map((r) => `| ${r.map(cell).join(' | ')} |`)].join('\n')
    : '_none_';

function specShapers(model, sec) {
  const out = [];
  for (const t of sortedTickets(model)) {
    if (t.status === 'cancelled') continue;
    for (const ref of t.touches.spec) {
      const { slug } = specRefParts(ref);
      const file = specRefFile(model.ctx, ref) ?? specRefParts(ref).file;
      if (file === sec.file && (!slug || slug === sec.slug)) {
        out.push(t);
        break;
      }
    }
  }
  return out;
}

function renderIndex(model) {
  const all = sortedTickets(model);
  const commit = (t) => (t.commitment ? `${t.commitment}${t.overdue ? ' ⚠ overdue' : ''}` : '—');
  const open = all.filter((t) => t.type !== 'epic' && !['done', 'cancelled'].includes(t.status) && !t.obsolete);
  const epics = all.filter((t) => t.type === 'epic');
  const closed = all.filter((t) => t.type !== 'epic' && (['done', 'cancelled'].includes(t.status) || t.obsolete));
  const parts = [];
  parts.push('<!-- GENERATED by `flow index` — do not edit, not versioned -->');
  parts.push('# Index', '', `Updated ${model.today}. Read this first; open a ticket or spec section only when the task needs it.`, '');
  parts.push('## Open work');
  parts.push(
    table(
      ['ID', 'Title', 'Type', 'Status', 'Epic', 'Module', 'Commitment', 'Depends on', 'Blocks'],
      open.map((t) => [t.id, t.title, t.quick ? `${t.type} (quick)` : t.type, t.status, t.epic ?? '—', listCell(t.module), commit(t), listCell(t.depends_on), listCell(t.blocks)]),
    ),
    '',
  );
  parts.push('## Epics');
  parts.push(
    table(
      ['ID', 'Title', 'Status', 'Progress', 'Commitment', 'Tickets'],
      epics.map((e) => [
        e.id,
        e.title,
        e.derived_status,
        `${e.progress.done}/${e.progress.total}`,
        commit(e),
        e.children.length ? e.children.map((c) => c + (model.tickets.get(c).status === 'done' ? ' ✓' : '')).join(', ') : '—',
      ]),
    ),
    '',
  );
  parts.push('## General spec sections');
  const secs = scanSpec(model.ctx);
  parts.push(
    table(
      ['Section', 'Summary', 'Last synced by', 'Tickets that shaped it'],
      secs.map((s) => {
        const sh = specShapers(model, s);
        const doneSh = sh.filter((t) => t.status === 'done').sort((a, b) => (a.finished ?? '').localeCompare(b.finished ?? ''));
        return [s.key, s.summary || '—', doneSh.length ? doneSh[doneSh.length - 1].id : '—', listCell(sh.map((t) => t.id))];
      }),
    ),
    '',
  );
  parts.push('## Closed (history: read only when the question is historical)');
  parts.push(
    table(
      ['ID', 'Title', 'Final status', 'Finished', 'Superseded by'],
      closed.map((t) => [t.id, t.title, t.status === 'cancelled' ? 'cancelled' : t.obsolete ? `${t.status} (obsolete)` : t.status, t.finished ?? '—', t.superseded_by ?? '—']),
    ),
    '',
  );
  return parts.join('\n');
}

// ---------------------------------------------------------------- board data

const median = (a) => {
  if (!a.length) return null;
  const s = [...a].sort((x, y) => x - y);
  const m = Math.floor(s.length / 2);
  return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2;
};

function weekStart(dateStr) {
  const d = new Date(dateStr + 'T00:00:00Z');
  d.setUTCDate(d.getUTCDate() - ((d.getUTCDay() + 6) % 7));
  return d.toISOString().slice(0, 10);
}

function boardData(model, { weeks = 8 } = {}) {
  const all = sortedTickets(model);
  const today = model.today;
  const tickets = all.map((t) => ({
    id: t.id,
    title: t.title,
    type: t.type,
    quick: t.quick,
    status: t.status,
    derived_status: t.derived_status,
    priority: t.priority,
    epic: t.epic,
    subproject: t.subproject,
    module: t.module,
    feature: t.feature,
    assignee: t.assignee,
    requester: t.requester,
    commitment: t.commitment,
    original_commitment: t.original_commitment,
    slips: t.slips,
    slip_days: t.slip_days,
    overdue: t.overdue,
    depends_on: t.depends_on,
    blocks: t.blocks,
    blocked_by: t.depends_on.filter((d) => model.tickets.get(d)?.status !== 'done'),
    superseded_by: t.superseded_by,
    obsolete: t.obsolete,
    progress: { total: t.items.length, impl: t.items.filter((i) => i.impl).length, spec: t.items.filter((i) => i.spec).length },
    manual_pending: t.manual_pending,
    items: t.items.map((i) => ({ id: i.id, desc: i.desc, verify: i.verify, impl: i.impl, spec: i.spec })),
    created: t.created,
    started: t.started,
    finished: t.finished,
    blocked_since: t.blockedSince,
    blocked_days: t.blockedDays,
    claude_md: t.claude_md,
    children: t.children ?? undefined,
    epic_progress: t.progress && t.type === 'epic' ? t.progress : undefined,
    log_tail: t.log.slice(-6),
  }));

  const scope = all.filter((t) => t.type !== 'epic' && t.status !== 'cancelled' && !t.obsolete);
  const doneT = scope.filter((t) => t.status === 'done');
  const items = scope.flatMap((t) => t.items);
  const progress = {
    tickets_done: doneT.length,
    tickets_total: scope.length,
    items_done: items.filter((i) => i.spec && i.impl).length,
    items_total: items.length,
  };

  const weekList = [];
  let ws = weekStart(today);
  for (let i = 0; i < weeks; i++) {
    weekList.unshift(ws);
    const d = new Date(ws + 'T00:00:00Z');
    d.setUTCDate(d.getUTCDate() - 7);
    ws = d.toISOString().slice(0, 10);
  }
  const throughput = weekList.map((w) => ({ week_start: w, tickets: 0, items: 0 }));
  const bump = (date, key) => {
    if (!date) return;
    const row = throughput.find((r) => r.week_start === weekStart(date));
    if (row) row[key]++;
  };
  for (const t of all) {
    if (t.type === 'epic') continue;
    if (t.status === 'done') bump(t.finished, 'tickets');
    for (const d of t.itemsClosed) bump(d, 'items');
  }

  const lead = doneT.filter((t) => t.created && t.finished).map((t) => daysBetween(t.created, t.finished));
  const cycle = doneT.filter((t) => t.started && t.finished).map((t) => daysBetween(t.started, t.finished));
  const withCommit = doneT.filter((t) => t.commitment && t.finished);
  const onTime = withCommit.filter((t) => t.finished <= t.commitment).length;

  const holdsBack = (id, seen = new Set()) => {
    for (const b of model.tickets.get(id)?.blocks ?? []) {
      const x = model.tickets.get(b);
      if (!x || seen.has(b) || ['done', 'cancelled'].includes(x.status)) continue;
      seen.add(b);
      holdsBack(b, seen);
    }
    return seen;
  };
  const stoppers = all
    .filter((t) => t.status === 'blocked')
    .map((t) => ({
      id: t.id,
      title: t.title,
      blocked_since: t.blockedSince,
      days: t.blockedSince ? daysBetween(t.blockedSince, today) : 0,
      holds_back: [...holdsBack(t.id)].sort(byId),
    }))
    .sort((a, b) => b.holds_back.length - a.holds_back.length || b.days - a.days);

  const loopActivity = all
    .flatMap((t) => t.log.filter((r) => r.action === 'loop').map((r) => ({ id: t.id, ...r })))
    .sort((a, b) => a.date.localeCompare(b.date))
    .slice(-20)
    .reverse();

  const byStatus = {};
  for (const t of all) if (t.type !== 'epic' && !t.obsolete) byStatus[t.status] = (byStatus[t.status] ?? 0) + 1;

  return {
    generated_at: today,
    project: { key: model.ctx.config.key, subprojects: model.ctx.config.subprojects },
    tickets,
    metrics: {
      progress,
      by_status: byStatus,
      throughput,
      lead_time_median_days: median(lead),
      cycle_time_median_days: median(cycle),
      on_time: { measured: withCommit.length, on_time: onTime, rate: withCommit.length ? onTime / withCommit.length : null },
      slipped_tickets: scope.filter((t) => t.slips > 0).length,
      total_slip_days: scope.reduce((n, t) => n + t.slip_days, 0),
      overdue: all.filter((t) => t.overdue).map((t) => t.id),
      stoppers,
      manual_pending: all.filter((t) => t.manual_pending > 0 && ['in_progress', 'validating'].includes(t.status)).map((t) => ({ id: t.id, title: t.title, pending: t.manual_pending })),
      loop_activity: loopActivity,
    },
  };
}


// ---------------------------------------------------------------- templates

const render = (tpl, vars) =>
  tpl.replace(/\{\{(\w+)\}\}/g, (_, k) => {
    if (!(k in vars)) fail(`internal: template variable ${k} is not set`);
    return String(vars[k]);
  });

const listOpt = (v) => (v === undefined || v === null || v === true || v === '' ? [] : Array.isArray(v) ? v : String(v).split(',').map((s) => s.trim()).filter(Boolean));

// ---------------------------------------------------------------- stamping managed fields

// blocks / superseded_by / obsolete are derived: rewrite them in place when they drift.
function stampManaged(ctx) {
  const loaded = loadAll(ctx);
  const model = buildModel(ctx, loaded);
  const changed = [];
  for (const [fid, t] of loaded.tickets) {
    const x = model.tickets.get(t.data.id ?? fid);
    if (!x) continue;
    const same = (a, b) => a.length === b.length && a.every((v, i) => v === b[i]);
    let touched = false;
    if (!same(x.fm.blocks, x.blocks)) {
      setFm(t, ['blocks'], x.blocks);
      touched = true;
    }
    if ((x.fm.superseded_by ?? null) !== x.superseded_by) {
      setFm(t, ['superseded_by'], x.superseded_by);
      touched = true;
    }
    if (x.fm.obsolete !== x.obsolete) {
      setFm(t, ['obsolete'], x.obsolete);
      touched = true;
    }
    if (touched) {
      writeText(t.file, t.text);
      changed.push(x.id);
    }
  }
  return changed;
}

function opIndex(ctx) {
  const stamped = stampManaged(ctx);
  const model = buildModel(ctx);
  fs.mkdirSync(path.dirname(ctx.indexPath), { recursive: true });
  writeText(ctx.indexPath, renderIndex(model));
  return { stamped, model };
}

// ---------------------------------------------------------------- new

function nextNumber(ctx) {
  let max = 0;
  if (fs.existsSync(ctx.ticketsDir)) {
    for (const f of fs.readdirSync(ctx.ticketsDir)) {
      const m = f.match(new RegExp(`^${ctx.config.key}-(\\d+)\\.md$`));
      if (m) max = Math.max(max, Number(m[1]));
    }
  }
  return max + 1;
}

function opNew(ctx, type, o = {}) {
  const cfg = ctx.config;
  if (!TYPES.includes(type)) fail(`Unknown type "${type}". Use one of: ${TYPES.join(', ')}`);
  if (!o.title || o.title === true) fail('--title "<text>" is required');
  const quick = !!o.quick;
  const reconcile = o.reconcile && o.reconcile !== true ? String(o.reconcile) : null;
  if (o.reconcile === true) fail('--reconcile needs a description of what was done (a commit range, a diff summary)');
  if (quick && !QUICK_TYPES.includes(type)) fail(`Quick tickets must be one of: ${QUICK_TYPES.join(', ')}`);
  if (reconcile && type === 'epic') fail('Epics cannot be reconciled');
  const priority = o.priority ?? 'medium';
  if (!PRIORITIES.includes(priority)) fail(`priority must be one of: ${PRIORITIES.join(', ')}`);
  if (o.commitment && !isDate(o.commitment)) fail('--commitment must be YYYY-MM-DD');
  const loaded = loadAll(ctx);
  const existing = loaded.tickets;
  const epic = o.epic && o.epic !== true ? o.epic : null;
  if (epic) {
    if (type === 'epic') fail('An epic cannot belong to another epic');
    const e = existing.get(epic);
    if (!e || e.data.type !== 'epic') fail(`--epic ${epic} is not an existing epic`);
  }
  const depends = listOpt(o['depends-on']);
  for (const d of depends) if (!existing.has(d)) fail(`depends-on ${d} does not exist`);
  const supersedes = listOpt(o.supersedes);
  if (supersedes.length && quick) fail('Quick tickets cannot supersede other tickets');
  for (const s of supersedes) if (!existing.has(s)) fail(`supersedes ${s} does not exist`);
  const subproject = listOpt(o.subproject);
  if (cfg.subprojects.length) for (const s of subproject) if (!cfg.subprojects.includes(s)) fail(`subproject "${s}" is not in the config (allowed: ${cfg.subprojects.join(', ')})`);

  const status = reconcile ? 'validating' : 'draft';
  const requester = o.requester && o.requester !== true ? o.requester : null;
  const tplName = type === 'epic' ? 'epic' : quick ? 'quick' : 'ticket';
  const today = todayStr();
  const createdReason = o.reason && o.reason !== true ? o.reason : requester ? `Initial definition requested by ${requester}` : 'Initial definition';

  fs.mkdirSync(ctx.ticketsDir, { recursive: true });
  let n = nextNumber(ctx);
  for (let attempt = 0; attempt < 25; attempt++, n++) {
    const id = `${cfg.key}-${n}`;
    const file = path.join(ctx.ticketsDir, `${id}.md`);
    const vars = {
      id,
      title: fmtScalar(String(o.title)),
      title_raw: String(o.title),
      type,
      status,
      priority,
      epic: fmtScalar(epic),
      subproject: fmtList(subproject),
      module: fmtList(listOpt(o.module)),
      feature: fmtList(listOpt(o.feature)),
      assignee: fmtScalar(o.assignee && o.assignee !== true ? o.assignee : null),
      requester: fmtScalar(requester),
      commitment_date: fmtScalar(o.commitment ?? null),
      depends_on: fmtList(depends),
      supersedes: fmtList(supersedes),
      today,
      created_reason: sanitizeCell(createdReason),
    };
    let text = render(TEMPLATES[tplName], vars);
    if (o.commitment) text = appendLogRow(text, { date: today, action: 'commitment', change: `commitment_date: null → ${o.commitment}`, reason: 'Initial commitment' });
    if (reconcile) text = appendLogRow(text, { date: today, action: 'reconciled', change: 'definition', reason: `Work done outside the flow: ${reconcile}` });
    try {
      fs.writeFileSync(file, text, { flag: 'wx' });
    } catch (e) {
      if (e.code === 'EEXIST') continue;
      throw e;
    }
    stampManaged(ctx);
    return { id, file, rel: posix(path.relative(ctx.root, file)) };
  }
  fail('Could not reserve a ticket ID (too many concurrent creations)');
}

// ---------------------------------------------------------------- set / log / item

function parseFieldValue(field, raw) {
  const listFields = ['subproject', 'module', 'feature', 'depends_on', 'supersedes', 'touches.spec', 'touches.scenarios', 'touches.code_scope'];
  if (listFields.includes(field)) {
    if (raw === 'null' || raw === '' || raw === '[]') return [];
    const v = raw.trim().startsWith('[') ? parseYaml(`x: ${raw}`).x : raw.split(',').map((s) => s.trim()).filter(Boolean);
    return v;
  }
  if (raw === 'null' || raw === '') return null;
  return raw;
}

const allowedTargets = (x) => {
  const base = [...(TRANSITIONS[x.status] ?? [])];
  if (x.status === 'blocked') {
    const last = [...x.statusHistory].reverse().find((h) => h.to === 'blocked');
    if (last && last.from !== 'null') base.push(last.from);
  }
  if (x.status === 'in_progress' && x.quick) base.push('done');
  return base;
};

const show = (v) => (Array.isArray(v) ? fmtList(v) : v === null || v === undefined ? 'null' : String(v));

function autoDraft(t, why) {
  setFm(t, ['status'], 'draft');
  logRow(t, 'status', 'status: approved → draft', why);
}

function opSet(ctx, id, field, raw, reason, opts = {}) {
  if (!reason || reason === true || !String(reason).trim()) fail('A reason is required: flow set <ID> <field> <value> "<reason>"');
  if (MANAGED_FIELDS.includes(field) || field === 'id') fail(`"${field}" is managed by the script and cannot be set by hand`);
  const loaded = loadAll(ctx);
  const t = loaded.tickets.get(id);
  if (!t) fail(`Ticket ${id} not found`);
  const model = buildModel(ctx, loaded);
  const x = model.tickets.get(id);
  const isEpic = x.type === 'epic';
  if (field === 'status') return opSetStatus(ctx, model, t, x, String(raw), String(reason));

  const settable = ['title', 'type', 'priority', 'epic', 'assignee', 'requester', 'commitment_date', 'subproject', 'module', 'feature', 'depends_on', 'supersedes', 'touches.spec', 'touches.scenarios', 'touches.code_scope', 'claude_md'];
  if (!settable.includes(field)) fail(`Unknown or read-only field "${field}". Settable: status, ${settable.join(', ')}`);
  if (isEpic && (field.startsWith('touches') || field === 'claude_md' || field === 'epic' || field === 'module' || field === 'feature')) fail(`"${field}" does not apply to epics`);
  const value = parseFieldValue(field, String(raw));
  const keys = field.split('.');
  const old = keys.length === 2 ? t.data.touches?.[keys[1]] : t.data[field];

  if (field === 'priority' && !PRIORITIES.includes(value)) fail(`priority must be one of: ${PRIORITIES.join(', ')}`);
  if (field === 'type') {
    if (!TYPES.includes(value) || value === 'epic' || isEpic) fail('type must be a non-epic type and epics cannot change type');
    if (x.quick && !QUICK_TYPES.includes(value)) fail('quick tickets must stay chore, bug or refactor');
  }
  if (field === 'claude_md' && !CLAUDE_MD_VALUES.includes(value)) fail(`claude_md must be one of: ${CLAUDE_MD_VALUES.join(', ')}`);
  if (field === 'commitment_date' && value !== null && !isDate(value)) fail('commitment_date must be YYYY-MM-DD or null');
  if (field === 'title' && !value) fail('title cannot be empty');
  if (field === 'epic' && value !== null) {
    const e = model.tickets.get(value);
    if (!e || e.type !== 'epic') fail(`${value} is not an existing epic`);
  }
  if (field === 'subproject' && ctx.config.subprojects.length) for (const s of value) if (!ctx.config.subprojects.includes(s)) fail(`subproject "${s}" is not in the config (allowed: ${ctx.config.subprojects.join(', ')})`);
  if (field === 'depends_on' || field === 'supersedes') {
    for (const d of value) {
      if (d === id) fail(`${field} cannot include the ticket itself`);
      if (!model.tickets.has(d)) fail(`${d} does not exist`);
    }
    if (field === 'supersedes' && x.quick && value.length) fail('Quick tickets cannot supersede other tickets');
  }
  if (field === 'touches.spec' && x.quick && value.length) fail('Quick tickets must not touch the general spec (use a normal ticket)');
  if (field === 'touches.scenarios' && x.quick && value.length) fail('Quick tickets must not declare scenarios (use a normal ticket)');

  const newShown = show(value);
  const oldShown = show(Array.isArray(value) ? asList(old) : old ?? null);
  if (newShown === oldShown) fail(`${field} is already ${newShown}`);
  setFm(t, keys, value);
  logRow(t, 'set', `${field}: ${oldShown} → ${newShown}`, reason);
  const notes = [];
  if (DEFINITION_FIELDS.includes(field) && t.data.status === 'approved') {
    autoDraft(t, `Definition changed after approval (${field}); needs re-approval`);
    notes.push('Ticket returned to draft (definition changed after approval).');
  }
  writeText(t.file, t.text);
  stampManaged(ctx);
  return notes;
}

function opSetStatus(ctx, model, t, x, to, reason) {
  const from = x.status;
  const valid = x.type === 'epic' ? EPIC_STATUSES : STATUSES;
  if (!valid.includes(to)) fail(`status must be one of: ${valid.join(', ')}`);
  if (from === to) fail(`Ticket is already ${to}`);
  if (x.type === 'epic') {
    if (to === 'cancelled' || (from === 'draft' && to === 'approved') || (from === 'approved' && to === 'draft')) {
      /* ok */
    } else if (from === 'cancelled') fail('A cancelled epic cannot change status');
    else fail(`Epic transition ${from} → ${to} is not allowed`);
  } else if (!allowedTargets(x).includes(to)) {
    fail(`Transition ${from} → ${to} is not allowed. From ${from} you can go to: ${allowedTargets(x).join(', ') || '(nowhere)'}`);
  }
  const problems = [];
  if (to === 'approved') {
    const r = checkReady(model, x.id);
    problems.push(...r.failures);
  }
  if (to === 'in_progress' && from === 'approved') {
    for (const d of x.depends_on) if (model.tickets.get(d)?.status !== 'done') problems.push(`dependency ${d} is not done yet (${model.tickets.get(d)?.status ?? 'missing'})`);
  }
  if (to === 'done') problems.push(...doneGate(x));
  if (problems.length) fail(`Cannot move ${x.id} to ${to}:\n  - ${problems.join('\n  - ')}`);
  setFm(t, ['status'], to);
  logRow(t, 'status', `status: ${from} → ${to}`, reason);
  writeText(t.file, t.text);
  stampManaged(ctx);
  return [];
}

function doneGate(x) {
  const p = [];
  if (x.type === 'epic') return p;
  if (x.claude_md === 'pending') p.push('claude_md is still pending: review the CLAUDE.md files and set it to updated or unchanged');
  for (const i of x.items) {
    if (!i.impl) p.push(`${i.id} is not implemented (impl: no)${i.verify === 'manual' ? ' and needs the author to confirm it' : ''}`);
    else if (!i.spec) p.push(`${i.id} is not synced into the general spec (spec: no)`);
  }
  if (x.malformed.length) p.push(`malformed checklist items: ${x.malformed.length}`);
  return p;
}

function opLog(ctx, id, action, reason, change) {
  if (!LOG_ACTIONS.includes(action)) fail(`Unknown log action "${action}". Allowed: ${LOG_ACTIONS.join(', ')}. Use \`flow set\` to change fields and \`flow item\` for checklist flags.`);
  const t = loadTicket(ctx, id);
  const notes = [];
  const defaultChange = { refined: 'definition', 'contradiction-check': 'check', loop: 'attempt', reconciled: 'definition' }[action];
  logRow(t, action, change && change !== true ? change : defaultChange, reason);
  if (action === 'refined' && t.data.status === 'approved') {
    autoDraft(t, 'Definition changed after approval; needs re-approval');
    notes.push('Ticket returned to draft (definition changed after approval).');
  }
  writeText(t.file, t.text);
  return notes;
}

function opItem(ctx, id, itemId, flag, value, reason, { byAuthor = false } = {}) {
  if (!['impl', 'spec'].includes(flag)) fail('flag must be impl or spec');
  if (!['yes', 'no'].includes(value)) fail('value must be yes or no');
  if (!reason || reason === true || !String(reason).trim()) fail('A reason is required: flow item <ID> <C#> impl|spec yes|no "<reason>"');
  const t = loadTicket(ctx, id);
  const status = t.data.status;
  if (!['in_progress', 'validating'].includes(status)) fail(`Checklist flags can only change while the ticket is in_progress or validating (it is ${status})`);
  const { items } = parseChecklist(t.body);
  const item = items.find((i) => i.id === itemId);
  if (!item) fail(`Checklist item ${itemId} not found in ${id}`);
  if (item[flag] === (value === 'yes')) fail(`${itemId}.${flag} is already ${value}`);
  if (flag === 'spec' && value === 'yes' && !item.impl) fail(`${itemId} cannot be synced into the spec before it is implemented`);
  if (flag === 'impl' && value === 'no' && item.spec) fail(`${itemId} is synced into the spec; set spec to no first`);
  if (flag === 'impl' && value === 'yes' && item.verify === 'manual' && !byAuthor) {
    fail(`${itemId} is verified manually: only the author can confirm it. Ask the author, then run with --by-author.`);
  }
  t.text = setItemFlag(t.text, itemId, flag, value === 'yes');
  logRow(t, 'item', `${itemId}.${flag}: ${item[flag] ? 'yes' : 'no'} → ${value}`, reason);
  writeText(t.file, t.text);
  return [];
}

// ---------------------------------------------------------------- config set

function opConfigSet(ctx, dotted, raw) {
  const keys = dotted.split('.');
  const value = raw === 'null' ? null : raw === 'true' ? true : raw === 'false' ? false : /^-?\d+$/.test(raw) ? Number(raw) : raw.trim().startsWith('[') ? parseYaml(`x: ${raw}`).x : raw;
  const text = setYamlPath(readText(ctx.configPath), keys, value);
  parseYaml(text, 'specs/flow.config.yml');
  writeText(ctx.configPath, text);
}

// ---------------------------------------------------------------- lock

function opLock(ctx, action, run) {
  const file = path.join(ctx.specsDir, '.flow.lock');
  const read = () => {
    try {
      return JSON.parse(fs.readFileSync(file, 'utf8'));
    } catch {
      return null;
    }
  };
  // The CLI process is short-lived, so a lock is held until released or 6 hours old.
  const alive = (l) => !!l && Date.now() - Date.parse(l.started) <= 6 * 3600 * 1000;
  if (action === 'status') {
    const l = read();
    return l && alive(l) ? `locked by run "${l.run}" since ${l.started}` : 'unlocked';
  }
  if (action === 'release') {
    fs.rmSync(file, { force: true });
    return 'released';
  }
  if (action === 'acquire') {
    const l = read();
    if (l && alive(l)) fail(`Another run is in progress: "${l.run}" since ${l.started}. Only one loop run per repository at a time.`);
    fs.writeFileSync(file, JSON.stringify({ run: run || 'run', started: new Date().toISOString() }));
    return 'acquired';
  }
  fail('lock action must be acquire, release or status');
}

// ---------------------------------------------------------------- init

function opInit(root, o = {}) {
  const key = o.key;
  if (!key || !/^[A-Z]{3,4}$/.test(key)) fail('--key must be 3-4 capital letters, e.g. --key VLT');
  const specs = path.join(root, 'specs');
  if (fs.existsSync(path.join(specs, 'flow.config.yml'))) fail('This project is already initialized (specs/flow.config.yml exists)');
  const subprojects = listOpt(o.subprojects);
  const testCommand = o['test-command'] && o['test-command'] !== true ? o['test-command'] : null;
  fs.mkdirSync(path.join(specs, 'general'), { recursive: true });
  fs.mkdirSync(path.join(specs, 'tickets'), { recursive: true });
  fs.mkdirSync(path.join(specs, '.flow'), { recursive: true });
  const cfgText = render(TEMPLATES.config, {
    key,
    test_command: fmtScalar(testCommand),
    subprojects: fmtList(subprojects),
    allowed_commands: fmtList(testCommand ? [testCommand] : []),
  });
  parseYaml(cfgText, 'generated config');
  writeText(path.join(specs, 'flow.config.yml'), cfgText);
  writeText(path.join(specs, 'general', 'overview.md'), TEMPLATES.overview);
  writeText(
    path.join(specs, 'FLOW.md'),
    render(TEMPLATES.flowmd, { key, general_spec: 'specs/general', index: 'specs/INDEX.md', tickets: 'specs/tickets' }),
  );
  fs.copyFileSync(fileURLToPath(import.meta.url), path.join(specs, '.flow', 'flow.mjs'));

  const claude = path.join(root, 'CLAUDE.md');
  if (!fs.existsSync(claude)) writeText(claude, `# ${path.basename(root)}\n\n@specs/FLOW.md\n`);
  else if (!readText(claude).includes('@specs/FLOW.md')) writeText(claude, readText(claude).replace(/\n*$/, '\n') + '\n@specs/FLOW.md\n');

  const gi = path.join(root, '.gitignore');
  const have = fs.existsSync(gi) ? readText(gi).split('\n') : [];
  const add = ['specs/INDEX.md', 'specs/.flow.lock'].filter((l) => !have.includes(l));
  if (add.length) writeText(gi, (have.join('\n').replace(/\n*$/, '') + '\n' + add.join('\n')).replace(/^\n/, ''));

  const ctx = loadProject(root);
  opIndex(ctx);
  return ctx;
}

// ---------------------------------------------------------------- migrate / upgrade

function opMigrate(ctx) {
  const current = ctx.config.flow_version;
  if (current === FLOW_VERSION) return `Format is up to date (flow_version ${FLOW_VERSION}).`;
  if (current > FLOW_VERSION) fail(`This project uses flow_version ${current}, newer than this script (${FLOW_VERSION}). Upgrade the script first: flow upgrade-script --from <path>`);
  fail(`No migration from flow_version ${current} is available`);
}

function opUpgradeScript(ctx, from) {
  if (!from || from === true) fail('--from <path to a newer flow.mjs> is required');
  const src = path.resolve(from);
  if (!fs.existsSync(src)) fail(`${src} not found`);
  const dest = path.join(ctx.specsDir, '.flow', 'flow.mjs');
  if (path.resolve(dest) === src) fail('Source and destination are the same file');
  fs.copyFileSync(src, dest);
  return dest;
}


// ---------------------------------------------------------------- scenario tags

const escRe = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

function scenarioTagRegex(cfg) {
  return new RegExp(`${escRe(cfg.traceability.scenario_tag)}[A-Za-z0-9_-]+`, 'g');
}
const tagToId = (tag) => tag.replace(/^@/, '');

function scenarioIdsIn(text, cfg) {
  return new Set((text.match(scenarioTagRegex(cfg)) ?? []).map(tagToId));
}

// ---------------------------------------------------------------- ready

const DEF_ROW = (r) => r.action === 'created' || r.action === 'refined' || (r.action === 'set' && DEFINITION_FIELDS.includes(parseChange(r.change)?.field));

function checkReady(model, id) {
  const x = model.tickets.get(id);
  if (!x) fail(`Ticket ${id} not found`);
  const failures = [];
  const warnings = [];
  const sec = (h) => getSection(x.body, h);

  const depProblems = () => {
    for (const d of x.depends_on) {
      const dep = model.tickets.get(d);
      if (!dep) failures.push(`depends_on ${d} does not exist`);
      else if (dep.status === 'cancelled' || dep.obsolete) failures.push(`depends_on ${d} is ${dep.status === 'cancelled' ? 'cancelled' : 'obsolete'}`);
    }
  };

  if (x.type === 'epic') {
    if (isBlankSection(sec('Goal'))) failures.push('"Goal" is empty');
    if (isBlankSection(sec('Done when'))) failures.push('"Done when" is empty');
    depProblems();
    return { failures, warnings };
  }

  if (x.quick) {
    if (isBlankSection(sec('What'))) failures.push('"What" is empty');
    if (isBlankSection(sec('Done when'))) failures.push('"Done when" is empty');
    if (!x.touches.code_scope.length) failures.push('touches.code_scope is empty');
    if (x.touches.spec.length) failures.push('quick tickets must not touch the general spec: make it a normal ticket');
    if (x.touches.scenarios.length) failures.push('quick tickets must not declare scenarios: make it a normal ticket');
    depProblems();
    return { failures, warnings };
  }

  if (isBlankSection(sec('Why'))) failures.push('"Why" is empty');
  const change = sec('Requested change') ?? '';
  const ci = change.indexOf('### Checklist');
  if (isBlankSection(ci >= 0 ? change.slice(0, ci) : change)) failures.push('"Requested change" is empty (describe the delta above the checklist)');

  if (!x.items.length) failures.push('the checklist has no items');
  if (x.malformed.length) failures.push(`malformed checklist items (expected "- [ ] C1 — text · verify: test · impl: no · spec: no"): ${x.malformed.length}`);
  for (const i of x.items) {
    if (i.desc.trim().startsWith('<')) failures.push(`${i.id} still has placeholder text`);
    if (!validVerify(i.verify)) failures.push(`${i.id} has an invalid verify kind "${i.verify}" (use test, command(<cmd>) or manual)`);
  }

  const bodyIds = scenarioIdsIn(stripHtmlComments(sec('Scenarios') ?? ''), model.ctx.config);
  if (x.items.some((i) => i.verify === 'test') && !x.touches.scenarios.length) failures.push('items verified by test need their scenarios listed in touches.scenarios');
  for (const s of x.touches.scenarios) if (!bodyIds.has(s)) failures.push(`scenario ${s} is in touches.scenarios but not written in the Scenarios section`);
  for (const s of bodyIds) if (!x.touches.scenarios.includes(s)) warnings.push(`scenario ${s} is written in the ticket but not listed in touches.scenarios`);

  if (!x.touches.spec.length) failures.push('touches.spec is empty (which general-spec sections does this change?)');
  if (!x.touches.code_scope.length) warnings.push('touches.code_scope is empty: the loop cannot run this ticket until it is set');
  if (!isBlankSection(sec('Open questions'))) failures.push('"Open questions" is not empty');
  depProblems();

  let lastDef = -1;
  let lastCheck = -1;
  x.log.forEach((r, i) => {
    if (DEF_ROW(r)) lastDef = i;
    if (r.action === 'contradiction-check') lastCheck = i;
  });
  if (lastCheck < lastDef || lastCheck < 0) failures.push('no contradiction check recorded after the latest definition change (run the check, then `flow log <ID> contradiction-check "<outcome>"`)');
  return { failures, warnings };
}

// ---------------------------------------------------------------- validate

const KNOWN_ACTIONS = ['created', 'status', 'set', 'item', 'commitment', ...LOG_ACTIONS];

function opValidate(ctx) {
  const loaded = loadAll(ctx);
  const model = buildModel(ctx, loaded);
  const errors = [...model.errors];
  const warnings = [];
  const E = (id, msg) => errors.push(`${id}: ${msg}`);
  const W = (id, msg) => warnings.push(`${id}: ${msg}`);
  const key = ctx.config.key;
  const specSections = scanSpec(ctx);
  const specFiles = new Map();
  const specScenarios = new Set();
  if (fs.existsSync(ctx.generalDir)) {
    for (const f of walkFiles(ctx.generalDir).filter((p) => p.endsWith('.md'))) for (const s of scenarioIdsIn(readText(path.join(ctx.generalDir, f)), ctx.config)) specScenarios.add(s);
  }
  for (const s of specSections) specFiles.set(s.key, s);

  const supersedeCount = new Map();
  for (const x of model.tickets.values()) {
    const id = x.id;
    if (x.fileId !== id) E(id, `file name ${x.fileId}.md does not match id ${id}`);
    if (!new RegExp(`^${key}-\\d+$`).test(id)) E(id, `id must look like ${key}-<number>`);
    if (!x.title) E(id, 'title is missing');
    if (!TYPES.includes(x.type)) E(id, `invalid type "${x.type}"`);
    const isEpic = x.type === 'epic';
    if (!(isEpic ? EPIC_STATUSES : STATUSES).includes(x.status)) E(id, `invalid status "${x.status}"`);
    if (!PRIORITIES.includes(x.priority)) E(id, `invalid priority "${x.priority}"`);
    if (x.commitment !== null && !isDate(x.commitment)) E(id, `commitment_date "${x.commitment}" is not YYYY-MM-DD`);
    if (!isEpic && !CLAUDE_MD_VALUES.includes(x.claude_md)) E(id, `invalid claude_md "${x.claude_md}"`);
    if (x.epic) {
      const e = model.tickets.get(x.epic);
      if (!e || e.type !== 'epic') E(id, `epic ${x.epic} does not exist or is not an epic`);
      if (isEpic) E(id, 'an epic cannot belong to another epic');
    }
    for (const d of x.depends_on) {
      if (d === id) E(id, 'depends_on includes itself');
      else if (!model.tickets.has(d)) E(id, `depends_on ${d} does not exist`);
    }
    for (const s of x.supersedes) {
      if (s === id) E(id, 'supersedes includes itself');
      else if (!model.tickets.has(s)) E(id, `supersedes ${s} does not exist`);
      else if (x.status !== 'cancelled') supersedeCount.set(s, [...(supersedeCount.get(s) ?? []), id]);
    }
    if (ctx.config.subprojects.length) for (const s of x.subproject) if (!ctx.config.subprojects.includes(s)) E(id, `subproject "${s}" is not in the config`);

    // managed fields
    const same = (a, b) => a.length === b.length && a.every((v, i) => v === b[i]);
    if (!same(x.fm.blocks, x.blocks) || (x.fm.superseded_by ?? null) !== x.superseded_by || x.fm.obsolete !== x.obsolete) E(id, 'managed fields (blocks, superseded_by, obsolete) are out of date: run `flow index`');

    // log
    if (!x.log.length || x.log[0].action !== 'created') E(id, 'the change log must start with a "created" row');
    for (const [i, r] of x.log.entries()) {
      if (!isDate(r.date)) E(id, `log row ${i + 1}: invalid date "${r.date}"`);
      if (!r.reason || r.reason === '—') E(id, `log row ${i + 1} (${r.action}): a reason is required`);
      if (!KNOWN_ACTIONS.includes(r.action)) W(id, `log row ${i + 1}: unknown action "${r.action}"`);
    }
    // status replay
    let prev = null;
    let beforeBlocked = null;
    for (const h of x.statusHistory) {
      if (prev === null) {
        if (h.from !== 'null') E(id, `first status row must start from null, got ${h.from}`);
      } else {
        if (h.from !== prev) E(id, `status log is inconsistent: expected "${prev} → …", found "${h.from} → ${h.to}"`);
        const ok = isEpic
          ? h.to === 'cancelled' || (prev === 'draft' && h.to === 'approved') || (prev === 'approved' && h.to === 'draft')
          : (TRANSITIONS[prev] ?? []).includes(h.to) || (prev === 'blocked' && h.to === beforeBlocked) || (x.quick && prev === 'in_progress' && h.to === 'done');
        if (!ok) E(id, `transition ${prev} → ${h.to} is not allowed`);
      }
      if (h.to === 'blocked') beforeBlocked = prev;
      prev = h.to;
    }
    if (prev !== null && prev !== x.status) E(id, `status in the frontmatter (${x.status}) does not match the log (${prev})`);
    // commitment vs log
    const commitRows = x.log.map((r) => parseChange(r.change)).filter((c) => c?.field === 'commitment_date');
    const lastCommit = commitRows.length ? commitRows[commitRows.length - 1].to : 'null';
    if ((x.commitment ?? 'null') !== lastCommit) W(id, `commitment_date (${x.commitment ?? 'null'}) does not match the log (${lastCommit}): change it with \`flow set\``);

    // checklist
    const seen = new Set();
    for (const i of x.items) {
      if (seen.has(i.id)) E(id, `duplicate checklist item ${i.id}`);
      seen.add(i.id);
      if (!validVerify(i.verify)) E(id, `${i.id}: invalid verify kind "${i.verify}"`);
      if (i.spec && !i.impl) E(id, `${i.id}: synced into the spec but not implemented`);
    }
    if (x.malformed.length) E(id, `malformed checklist items: ${x.malformed.length}`);
    if (x.status === 'done') for (const p of doneGate(x)) E(id, `done but ${p}`);

    // quick
    if (x.quick) {
      if (!QUICK_TYPES.includes(x.type)) E(id, 'quick tickets must be chore, bug or refactor');
      if (x.touches.spec.length || x.touches.scenarios.length) E(id, 'quick tickets must not touch the spec or declare scenarios');
      if (x.supersedes.length) E(id, 'quick tickets cannot supersede');
    }

    // touches
    const strict = ['validating', 'done'].includes(x.status) && !x.obsolete;
    for (const ref of x.touches.spec) {
      const file = specRefFile(ctx, ref);
      const { slug } = specRefParts(ref);
      if (!file) (strict ? E : W)(id, `touches.spec "${ref}": file not found in the general spec`);
      else if (slug && !specFiles.has(`${file}#${slug}`)) (strict ? E : W)(id, `touches.spec "${ref}": no heading with that anchor`);
    }
    if (x.status === 'done' && !x.obsolete) for (const s of x.touches.scenarios) if (!specScenarios.has(s)) E(id, `scenario ${s} is not in the general spec although the ticket is done`);
    if (['approved', 'in_progress', 'validating', 'done'].includes(x.status) && !isEpic && !x.quick) {
      const ids = scenarioIdsIn(stripHtmlComments(getSection(x.body, 'Scenarios') ?? ''), ctx.config);
      for (const s of x.touches.scenarios) if (!ids.has(s)) W(id, `scenario ${s} in touches.scenarios is not written in the ticket`);
    }

    // dates
    if (x.commitment && x.epic) {
      const e = model.tickets.get(x.epic);
      if (e?.commitment && x.commitment > e.commitment) W(id, `commitment ${x.commitment} is later than its epic ${e.id} (${e.commitment})`);
    }
    for (const d of x.depends_on) {
      const dep = model.tickets.get(d);
      if (dep?.commitment && x.commitment && x.commitment < dep.commitment) W(id, `commitment ${x.commitment} is earlier than its dependency ${d} (${dep.commitment})`);
    }
  }
  for (const [target, by] of supersedeCount) if (by.length > 1) E(target, `is superseded by more than one ticket (${by.join(', ')}); a ticket can be superseded only once`);

  // cycles
  const state = new Map();
  const visit = (id, trail) => {
    if (state.get(id) === 2) return;
    if (state.get(id) === 1) {
      E(id, `dependency cycle: ${[...trail, id].join(' → ')}`);
      return;
    }
    state.set(id, 1);
    for (const d of model.tickets.get(id)?.depends_on ?? []) if (model.tickets.has(d)) visit(d, [...trail, id]);
    state.set(id, 2);
  };
  for (const id of model.tickets.keys()) visit(id, []);
  return { errors, warnings };
}

// ---------------------------------------------------------------- drift

function opDrift(ctx, o = {}) {
  const cfg = ctx.config;
  const model = buildModel(ctx);
  const out = { untested: [], unknown_tags: [], pending_sync: [], commits_without_ticket: [], notes: [] };

  const specTags = new Set();
  if (fs.existsSync(ctx.generalDir)) for (const f of walkFiles(ctx.generalDir).filter((p) => p.endsWith('.md'))) for (const s of scenarioIdsIn(readText(path.join(ctx.generalDir, f)), cfg)) specTags.add(s);

  const globs = asList(cfg.traceability.test_globs).map(globToRegex);
  if (!globs.length) out.notes.push('traceability.test_globs is empty: scenario ↔ test traceability was not checked');
  else {
    const testTags = new Set();
    for (const f of walkFiles(ctx.root)) {
      if (!globs.some((g) => g.test(f))) continue;
      for (const s of scenarioIdsIn(readText(path.join(ctx.root, f)), cfg)) testTags.add(s);
    }
    const pending = new Set();
    for (const t of model.tickets.values()) if (!['done', 'cancelled'].includes(t.status) && !t.obsolete) for (const s of t.touches.scenarios) pending.add(s);
    out.untested = [...specTags].filter((s) => !testTags.has(s)).sort();
    for (const s of [...testTags].sort()) {
      if (specTags.has(s)) continue;
      (pending.has(s) ? out.pending_sync : out.unknown_tags).push(s);
    }
  }

  try {
    execFileSync('git', ['rev-parse', '--git-dir'], { cwd: ctx.root, stdio: 'ignore' });
    const range = o.since && o.since !== true ? [`${o.since}..HEAD`] : [];
    const limit = String(o.limit && o.limit !== true ? o.limit : 200);
    const log = execFileSync('git', ['log', '--no-merges', '-n', limit, '--pretty=format:@@%H%x09%s', '--name-only', ...range], { cwd: ctx.root, encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] });
    const idRe = new RegExp(`^${cfg.key}-\\d+`);
    let cur = null;
    const commits = [];
    for (const line of log.split('\n')) {
      if (line.startsWith('@@')) {
        const [hash, ...subj] = line.slice(2).split('\t');
        cur = { hash: hash.slice(0, 8), subject: subj.join('\t'), files: [] };
        commits.push(cur);
      } else if (line.trim() && cur) cur.files.push(line.trim());
    }
    const meta = new Set(['CLAUDE.md', '.gitignore']);
    for (const c of commits) {
      if (idRe.test(c.subject)) continue;
      const code = c.files.filter((f) => !f.startsWith('specs/') && !meta.has(f));
      if (code.length) out.commits_without_ticket.push({ commit: c.hash, subject: c.subject, files: code.length });
    }
  } catch {
    out.notes.push('not a git repository (or git is unavailable): commit conventions were not checked');
  }
  return out;
}


// ---------------------------------------------------------------- CLI

const BOOLEAN_FLAGS = new Set(['json', 'quick', 'by-author', 'help']);

function parseArgs(argv) {
  const pos = [];
  const opt = {};
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a.startsWith('--') && a.length > 2) {
      const eq = a.indexOf('=');
      const name = eq > 0 ? a.slice(2, eq) : a.slice(2);
      if (eq > 0) opt[name] = a.slice(eq + 1);
      else if (BOOLEAN_FLAGS.has(name)) opt[name] = true;
      else if (i + 1 < argv.length && !argv[i + 1].startsWith('--')) opt[name] = argv[++i];
      else opt[name] = true;
    } else pos.push(a);
  }
  return { pos, opt };
}

const HELP = `flow — ticket-driven spec workflow (v${SCRIPT_VERSION}, flow_version ${FLOW_VERSION})

Usage: node specs/.flow/flow.mjs <command> [args] [--json]

Setup
  init --key ABC [--subprojects a,b] [--test-command "npm test"]
  migrate                       Check/upgrade the on-disk format
  upgrade-script --from <path>  Replace the vendored script with a newer one
  config get <path> | config set <path> <value>

Tickets
  new <type> --title "…" [--quick] [--reconcile "<commit range or what was done>"] [--priority p] [--commitment YYYY-MM-DD]
      [--epic ID] [--depends-on A,B] [--supersedes A] [--subproject s] [--module m] [--feature f]
      [--assignee x] [--requester x] [--reason "…"]
      types: ${TYPES.join(', ')}
  set <ID> <field> <value> "<reason>"       field "status" runs the transition gates
  log <ID> <action> "<reason>" [--change "…"]   actions: ${LOG_ACTIONS.join(', ')}
  item <ID> <C#> impl|spec yes|no "<reason>" [--by-author]
  ready <ID>                    Definition of Ready check
  show <ID> | list [--status s] [--type t]

Project
  index                         Stamp managed fields and regenerate specs/INDEX.md
  validate                      Consistency check (exit 1 on errors)
  drift [--since <ref>] [--limit n]   Scenario↔test traceability and commits without ticket
  board-data [--weeks n] [--out file]   JSON snapshot for the kanban board
  lock acquire [run-name] | lock release | lock status
  version

Every change to a ticket needs a reason; the script appends it to the ticket's change log.`;

const out = (s = '') => process.stdout.write(s + '\n');
const err = (s) => process.stderr.write(s + '\n');
const need = (v, what) => {
  if (v === undefined || v === true || v === '') fail(`Missing ${what}. Run \`flow help\`.`);
  return String(v);
};
const jsonOut = (o) => out(JSON.stringify(o, null, 2));

function brief(x) {
  return {
    id: x.id, title: x.title, type: x.type, status: x.status, priority: x.priority, quick: !!x.quick,
    epic: x.epic ?? null, depends_on: x.depends_on, blocks: x.blocks, supersedes: x.supersedes, superseded_by: x.superseded_by,
    obsolete: x.obsolete, commitment_date: x.commitment ?? null, original_commitment: x.original_commitment ?? null,
    slip_days: x.slip_days ?? null, overdue: !!x.overdue, claude_md: x.claude_md,
    items: x.items.map((i) => ({ id: i.id, verify: i.verify, impl: i.impl, spec: i.spec })),
    touches: x.touches, manual_pending: x.manual_pending ?? null,
  };
}

function main(argv) {
  const { pos, opt } = parseArgs(argv);
  const cmd = pos[0];
  const json = !!opt.json;
  if (!cmd || cmd === 'help' || opt.help) return out(HELP);
  if (cmd === 'version') return out(`${SCRIPT_VERSION} (flow_version ${FLOW_VERSION})`);

  if (cmd === 'init') {
    const root = opt.root && opt.root !== true ? path.resolve(opt.root) : process.cwd();
    const ctx = opInit(root, opt);
    return out(`Initialized ticket-spec-flow in ${ctx.root}\n  specs/flow.config.yml, specs/FLOW.md, specs/general/overview.md, specs/.flow/flow.mjs\n  CLAUDE.md now imports @specs/FLOW.md\nNext: edit specs/general/overview.md, then \`node specs/.flow/flow.mjs new feature --title "…"\``);
  }

  const ctx = loadProject();

  switch (cmd) {
    case 'new': {
      const r = opNew(ctx, need(pos[1], 'ticket type'), opt);
      opIndex(ctx);
      return json ? jsonOut(r) : out(`Created ${r.id} → ${r.rel}`);
    }
    case 'set': {
      const id = need(pos[1], 'ticket ID');
      const notes = opSet(ctx, id, need(pos[2], 'field'), need(pos[3], 'value'), pos[4]);
      opIndex(ctx);
      out(`${id}: ${pos[2]} updated.`);
      for (const n of notes ?? []) out(`  ${n}`);
      return;
    }
    case 'log': {
      const id = need(pos[1], 'ticket ID');
      const notes = opLog(ctx, id, need(pos[2], 'action'), need(pos[3], 'reason'), opt.change);
      opIndex(ctx);
      out(`${id}: logged ${pos[2]}.`);
      for (const n of notes) out(`  ${n}`);
      return;
    }
    case 'item': {
      const id = need(pos[1], 'ticket ID');
      opItem(ctx, id, need(pos[2], 'item ID'), need(pos[3], 'flag'), need(pos[4], 'value'), pos[5], { byAuthor: !!opt['by-author'] });
      opIndex(ctx);
      return out(`${id}: ${pos[2]}.${pos[3]} → ${pos[4]}`);
    }
    case 'ready': {
      const id = need(pos[1], 'ticket ID');
      const r = checkReady(buildModel(ctx), id);
      if (json) jsonOut(r);
      else if (!r.failures.length) {
        out(`${id} is ready.`);
        for (const w of r.warnings) out(`  warning: ${w}`);
      } else {
        out(`${id} is NOT ready:`);
        for (const f of r.failures) out(`  - ${f}`);
        for (const w of r.warnings) out(`  warning: ${w}`);
      }
      if (r.failures.length) process.exitCode = 1;
      return;
    }
    case 'index': {
      const { stamped } = opIndex(ctx);
      return out(`Index regenerated (${path.relative(ctx.root, ctx.indexPath)}).${stamped.length ? ` Managed fields updated in: ${stamped.join(', ')}.` : ''}`);
    }
    case 'validate': {
      const r = opValidate(ctx);
      if (json) jsonOut(r);
      else {
        for (const e of r.errors) out(`ERROR   ${e}`);
        for (const w of r.warnings) out(`warning ${w}`);
        out(r.errors.length ? `${r.errors.length} error(s), ${r.warnings.length} warning(s).` : `OK — ${r.warnings.length} warning(s).`);
      }
      if (r.errors.length) process.exitCode = 1;
      return;
    }
    case 'drift': {
      const r = opDrift(ctx, opt);
      if (json) return jsonOut(r);
      out(`Scenarios in the spec without a test tag: ${r.untested.length}`);
      for (const s of r.untested) out(`  - ${s}`);
      out(`Test tags unknown to the spec and to any open ticket: ${r.unknown_tags.length}`);
      for (const s of r.unknown_tags) out(`  - ${s}`);
      out(`Test tags waiting for their ticket to sync the spec: ${r.pending_sync.length}`);
      for (const s of r.pending_sync) out(`  - ${s}`);
      out(`Commits touching code without a ${ctx.config.key}-n prefix: ${r.commits_without_ticket.length}`);
      for (const c of r.commits_without_ticket) out(`  - ${c.commit} ${c.subject} (${c.files} file(s))`);
      for (const n of r.notes) out(`note: ${n}`);
      if (r.untested.length || r.unknown_tags.length || r.commits_without_ticket.length) process.exitCode = 1;
      return;
    }
    case 'board-data': {
      const weeks = opt.weeks && opt.weeks !== true ? Number(opt.weeks) : 8;
      stampManaged(ctx);
      const data = boardData(buildModel(ctx), { weeks });
      const text = JSON.stringify(data, null, 2);
      if (opt.out && opt.out !== true) {
        fs.writeFileSync(path.resolve(opt.out), text + '\n');
        return out(`Board data written to ${opt.out}`);
      }
      return out(text);
    }
    case 'config': {
      const sub = pos[1];
      if (sub === 'get') {
        let v = ctx.config;
        for (const k of need(pos[2], 'config path').split('.')) v = v?.[k];
        return out(v === undefined || v === null ? 'null' : typeof v === 'object' ? JSON.stringify(v) : String(v));
      }
      if (sub === 'set') {
        opConfigSet(ctx, need(pos[2], 'config path'), need(pos[3], 'value'));
        return out(`${pos[2]} = ${pos[3]}`);
      }
      return fail('config needs get <path> or set <path> <value>');
    }
    case 'migrate':
      return out(opMigrate(ctx));
    case 'upgrade-script':
      return out(`Script replaced: ${opUpgradeScript(ctx, opt.from)}`);
    case 'lock':
      return out(opLock(ctx, need(pos[1], 'lock action'), pos[2]));
    case 'show': {
      const id = need(pos[1], 'ticket ID');
      const x = buildModel(ctx).tickets.get(id);
      if (!x) fail(`Ticket ${id} not found`);
      return jsonOut(brief(x));
    }
    case 'list': {
      const rows = sortedTickets(buildModel(ctx)).filter((x) => (!opt.status || x.status === opt.status) && (!opt.type || x.type === opt.type));
      if (json) return jsonOut(rows.map(brief));
      for (const x of rows) out(`${x.id}\t${x.status}${x.obsolete ? '*' : ''}\t${x.type}\t${x.priority}\t${x.commitment ?? '-'}\t${x.title}`);
      return;
    }
    default:
      fail(`Unknown command "${cmd}". Run \`flow help\`.`);
  }
}

const invokedDirectly = process.argv[1] && import.meta.url === pathToFileURL(fs.realpathSync(process.argv[1])).href;
if (invokedDirectly) {
  try {
    main(process.argv.slice(2));
  } catch (e) {
    if (e instanceof FlowError) {
      err(`flow: ${e.message}`);
      process.exitCode = 1;
    } else {
      err(e.stack || String(e));
      process.exitCode = 2;
    }
  }
}

